import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { BarProgressProps } from "./bar-progress.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

const componentName = "BarProgress";

export const BarProgressClasses = {
  root: "exp-textura_bar-progress",
  track: "exp-textura_bar-progress_track",
  indicatorDeterminate: "exp-textura_bar-progress_indicator_determinate",
  indicatorIndeterminate: "exp-textura_bar-progress_indicator_indeterminate",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  inverse: {
    track: { backgroundColor: theme.progress.color.inverse.track },
    indicatorDeterminate: { backgroundColor: theme.progress.color.inverse.indicator },
    indicatorIndeterminate: { backgroundColor: theme.progress.color.inverse.indicator },
  },
});

const generateStyles = (props: BarProgressProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<BarProgressProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "block",
    textAlign: "center",
    width: "auto",

    [`& .${BarProgressClasses.track}`]: {
      overflow: "hidden",
      position: "relative",
      backgroundColor: theme.progress.color.default.track,
      borderRadius: theme.toRem(theme.border.radius.sm),
      height: theme.toRem(theme.spacing[8]),
      width: "100%",
      ":dir(rtl)": {
        transform: "scale(-1, 1)",
      },
      ...styleSlots?.track,
    },

    [`& .${BarProgressClasses.indicatorDeterminate}`]: {
      backgroundColor: theme.progress.color.default.indicator,
      height: "100%",
      width: "100%",
      transition: "transform 660ms cubic-bezier(0.65, 0, 0.35, 1)",
      animation: undefined,
      ...styleSlots?.indicatorDeterminate,
    },

    [`& .${BarProgressClasses.indicatorIndeterminate}`]: {
      backgroundColor: theme.progress.color.default.indicator,
      height: "100%",
      width: "50%",
      transition: undefined,
      animation: "exp-textura-bar-progress-indeterminate 1.2s infinite linear",
      ...styleSlots?.indicatorIndeterminate,
    },

    "@keyframes exp-textura-bar-progress-indeterminate": {
      "0%": {
        transform: "translateX(-200%)",
      },
      "100%": {
        transform: "translateX(200%)",
      },
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps("progressType");

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledBarProgress = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<BarProgressProps>((props) => generateStyles(props));
